// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        address expectedCEO = c.ceoAddress();

        vm.prank(attacker);
        (bool success, ) = address(c).call(abi.encodeWithSignature("DrugDealer()"));

        bool ceoChanged = (c.ceoAddress() != expectedCEO);

        assertTrue(!(success && ceoChanged));
    }
}
